CREATE TABLE IF NOT EXISTS users (id BINARY(16) NOT NULL,name VARCHAR(100) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;CREATE TABLE IF NOT EXISTS products (id BINARY(16) NOT NULL,name VARCHAR(150) NOT NULL,price_cents BIGINT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;CREATE TABLE IF NOT EXISTS orders (id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,total_cents BIGINT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY (id),INDEX idx_orders_user_id (user_id),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;CREATE TABLE IF NOT EXISTS order_items (id BINARY(16) NOT NULL,order_id BINARY(16) NOT NULL,product_id BINARY(16) NOT NULL,qty INT NOT NULL,price_cents BIGINT NOT NULL,PRIMARY KEY (id),INDEX idx_items_order_id (order_id),INDEX idx_items_product_id (product_id),FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;